-- ─────────────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS "memorymatch_games" (
  id                  TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
  "familyId"          TEXT NOT NULL,
  "hostUserId"        TEXT NOT NULL,
  "hostUserName"      TEXT NOT NULL DEFAULT 'Host',
  "roomName"          TEXT,
  status              TEXT NOT NULL DEFAULT 'waiting',  -- waiting|in_progress|completed|cancelled
  "difficulty"        TEXT NOT NULL DEFAULT 'auto',     -- auto|easy|medium|hard|expert
  "cardPack"          TEXT,                             -- classic|family|food|animals (picked at start)
  "turnSeconds"       INTEGER NOT NULL DEFAULT 15,      -- per-turn timer
  "maxPlayers"        INTEGER NOT NULL DEFAULT 4,
  cards               JSONB NOT NULL DEFAULT '[]'::jsonb,
  -- card = {"p": pairId, "k": symbolKey, "o": ownerUserId|null} (array index = card id)
  "playerOrder"       JSONB NOT NULL DEFAULT '[]'::jsonb,   -- userIds in seat order
  "currentPlayerId"   TEXT,
  "currentTurnIndex"  INTEGER NOT NULL DEFAULT 0,
  "turnEndsAt"        TIMESTAMPTZ,
  phase               TEXT NOT NULL DEFAULT 'turn',     -- turn|reveal
  "flippedCardIds"    JSONB NOT NULL DEFAULT '[]'::jsonb,  -- indices flipped this turn
  "revealEndsAt"      TIMESTAMPTZ,
  "pendingResult"     JSONB,                            -- {ids:[a,b], isMatch:bool}
  "scores"            JSONB NOT NULL DEFAULT '{}'::jsonb,  -- userId → pairs owned
  "stats"             JSONB NOT NULL DEFAULT '{}'::jsonb,  -- userId → {flips, misses, matchMs}
  "placements"        JSONB NOT NULL DEFAULT '[]'::jsonb,  -- final ranking
  "winnerUserIds"     JSONB NOT NULL DEFAULT '[]'::jsonb,
  "endReason"         TEXT,                             -- all_found|walkover
  "startedAt"         TIMESTAMPTZ,
  "completedAt"       TIMESTAMPTZ,
  "createdAt"         TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- shared temporary-room lifecycle columns (see 20260913120000)
  "autoCloseDeadline" TIMESTAMPTZ,
  "cancelledAt"       TIMESTAMPTZ,
  "closedAt"          TIMESTAMPTZ,
  "hostReady"         BOOLEAN DEFAULT true,
  "spectatorsEnabled" BOOLEAN DEFAULT true,
  "lastActivityAt"    TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS "memorymatch_players" (
  id                TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
  "gameId"          TEXT NOT NULL REFERENCES "memorymatch_games"(id) ON DELETE CASCADE,
  "userId"          TEXT NOT NULL,
  "userName"        TEXT NOT NULL,
  "isReady"         BOOLEAN NOT NULL DEFAULT false,
  "readyAt"         TIMESTAMPTZ,
  "joinedAt"        TIMESTAMPTZ NOT NULL DEFAULT now(),
  "lastActivityAt"  TIMESTAMPTZ DEFAULT now(),
  "leftAt"          TIMESTAMPTZ,                        -- mid-game departure (row kept for archive)
  UNIQUE ("gameId", "userId")
);

CREATE INDEX IF NOT EXISTS idx_memorymatch_players_game ON "memorymatch_players" ("gameId");
CREATE INDEX IF NOT EXISTS idx_memorymatch_games_family_status ON "memorymatch_games" ("familyId", "status");

